pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const users = pm.response.json();

pm.test("Response is an array", function () {
    pm.expect(users).to.be.an("array");
});

pm.test("User array is not empty", function () {
    pm.expect(users.length).to.be.greaterThan(0);
});

pm.test("Users contain id, name and email", function () {
    users.forEach(user => {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
});

// Save the first user for Request 2
const selectedUser = users[0];

pm.collectionVariables.set(
    "userId",
    String(selectedUser.id)
);

pm.collectionVariables.set(
    "selectedUser",
    JSON.stringify(selectedUser)
);

console.log("Saved user ID:", selectedUser.id);

// Retrieve the original user saved by GET
const originalUser = JSON.parse(
    pm.collectionVariables.get("selectedUser")
);

// Generate dynamic values for every execution
const runId = Date.now();

const updatedName = `SQA Student ${runId}`;
const updatedEmail = `sqa_${runId}@example.com`;
const updatedCompanyName = `QA Company ${runId}`;

// Update only the required fields
const updatedUser = {
    ...originalUser,
    name: updatedName,
    email: updatedEmail,
    company: {
        ...originalUser.company,
        name: updatedCompanyName
    }
};

// Prepare the request body
pm.variables.set(
    "putUserBody",
    JSON.stringify(updatedUser)
);

// Save expected values for response validation
pm.collectionVariables.set("updatedName", updatedName);
pm.collectionVariables.set("updatedEmail", updatedEmail);
pm.collectionVariables.set("updatedCompanyName", updatedCompanyName);

console.log("Updating user ID:", pm.collectionVariables.get("userId"));
console.log("Updated name:", updatedName);
console.log("Updated email:", updatedEmail);
console.log("Updated company:", updatedCompanyName);

const response = pm.response.json();
const userId = pm.collectionVariables.get("userId");
const updatedName = pm.collectionVariables.get("updatedName");

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Returned ID matches saved user ID", function () {
    pm.expect(String(response.id)).to.eql(String(userId));
});

pm.test("Phone number is not empty", function () {
    pm.expect(response.phone).to.be.a("string").and.not.empty;
});

pm.test("Name matches updated name", function () {
    pm.expect(response.name).to.eql(updatedName);
});

pm.test("Email matches updated email", function () {
    pm.expect(response.email).to.eql(
        pm.collectionVariables.get("updatedEmail")
    );
});

pm.test("Company name matches updated company name", function () {
    pm.expect(response.company.name).to.eql(
        pm.collectionVariables.get("updatedCompanyName")
    );
});
